@extends('layouts.portal', ['role' => 'secretariat', 'roleName' => 'Sekretariat', 'nav' => $secNav, 'title' => 'Manajemen konten'])

@section('content')
<main class="space-y-5" x-data="{
    tab: 'events', events: [], rows: [], loading: true, error: '', formError: '', modal: false, editing: null, saving: false,
    eventForm: { nama_event: '', tema: '', deskripsi: '', tanggal_mulai: '', tanggal_selesai: '', lokasi: '', mode_kegiatan: 'Hybrid', status_event: 'Draft' },
    speakerForm: { id_event: '', nama_speaker: '', institusi: '', negara: '', deskripsi: '' },
    scheduleForm: { id_event: '', nama_kegiatan: '', tanggal: '', waktu_mulai: '', waktu_selesai: '', lokasi: '', deskripsi: '' },
    endpoints: { events: '/api/content/events', speakers: '/api/content/speakers', schedules: '/api/content/schedules' },
    async init() { await this.load(); },
    async load() { this.loading = true; this.error = ''; const result = await window.asicApi.get(this.endpoints[this.tab], { per_page: 100 }); this.loading = false; if (!result.ok) { this.error = result.error || 'Konten gagal dimuat.'; return; } this.rows = result.data?.data || []; if (this.tab === 'events') this.events = this.rows; },
    resetForm() { this.editing = null; this.formError = ''; this.eventForm = { nama_event: '', tema: '', deskripsi: '', tanggal_mulai: '', tanggal_selesai: '', lokasi: '', mode_kegiatan: 'Hybrid', status_event: 'Draft' }; this.speakerForm = { id_event: this.events[0]?.id_event || '', nama_speaker: '', institusi: '', negara: '', deskripsi: '' }; this.scheduleForm = { id_event: this.events[0]?.id_event || '', nama_kegiatan: '', tanggal: '', waktu_mulai: '', waktu_selesai: '', lokasi: '', deskripsi: '' }; this.modal = true; },
    edit(row) { this.editing = this.tab === 'events' ? row.id_event : (this.tab === 'speakers' ? row.id_speaker : row.id_schedule); this.formError = ''; if (this.tab === 'events') this.eventForm = { nama_event: row.nama_event, tema: row.tema || '', deskripsi: row.deskripsi || '', tanggal_mulai: (row.tanggal_mulai || '').slice(0,10), tanggal_selesai: (row.tanggal_selesai || '').slice(0,10), lokasi: row.lokasi || '', mode_kegiatan: row.mode_kegiatan, status_event: row.status_event }; else if (this.tab === 'speakers') this.speakerForm = { id_event: row.id_event, nama_speaker: row.nama_speaker, institusi: row.institusi || '', negara: row.negara || '', deskripsi: row.deskripsi || '' }; else this.scheduleForm = { id_event: row.id_event, nama_kegiatan: row.nama_kegiatan, tanggal: (row.tanggal || '').slice(0,10), waktu_mulai: (row.waktu_mulai || '').slice(0,5), waktu_selesai: (row.waktu_selesai || '').slice(0,5), lokasi: row.lokasi || '', deskripsi: row.deskripsi || '' }; this.modal = true; },
    async save() { this.saving = true; this.formError = ''; const payload = this.tab === 'events' ? this.eventForm : (this.tab === 'speakers' ? this.speakerForm : this.scheduleForm); const endpoint = this.endpoints[this.tab] + (this.editing ? '/' + this.editing : ''); const result = this.editing ? await window.asicApi.patch(endpoint, payload) : await window.asicApi.post(endpoint, payload); this.saving = false; if (!result.ok) { this.formError = result.error || Object.values(result.errors || {}).flat().join(' '); return; } this.modal = false; await this.load(); },
    async remove(row) { const id = this.tab === 'events' ? row.id_event : (this.tab === 'speakers' ? row.id_speaker : row.id_schedule); if (!confirm('Hapus konten ini?')) return; const result = await window.asicApi.delete(this.endpoints[this.tab] + '/' + id); if (!result.ok) { this.error = result.error || 'Konten gagal dihapus.'; return; } await this.load(); }
}">
    <header class="flex flex-wrap items-end justify-between gap-4 rounded-2xl bg-surface-container-low p-6"><div><p class="text-xs font-bold uppercase tracking-widest text-primary">Website ASIC</p><h1 class="mt-1 text-2xl font-bold">Manajemen konten website</h1><p class="mt-1 text-sm text-on-surface-variant">Kelola event, pembicara, dan jadwal konferensi. Ringkasan mengikuti bagian yang dipilih.</p></div><button @click="resetForm()" class="rounded-xl bg-primary px-4 py-2 text-sm font-semibold text-white">Tambah konten</button></header>
    <section class="grid gap-3 sm:grid-cols-3"><article class="rounded-xl border border-surface-container-high bg-surface-container-lowest p-4"><p class="text-xs uppercase text-on-surface-variant">Data pada bagian ini</p><strong class="mt-1 block text-2xl" x-text="rows.length"></strong></article><article x-show="tab==='events'" class="rounded-xl border border-surface-container-high bg-surface-container-lowest p-4"><p class="text-xs uppercase text-on-surface-variant">Event aktif</p><strong class="mt-1 block text-2xl" x-text="rows.filter(row => row.status_event === 'Aktif').length"></strong></article><article x-show="tab==='speakers'" class="rounded-xl border border-surface-container-high bg-surface-container-lowest p-4"><p class="text-xs uppercase text-on-surface-variant">Event terkait</p><strong class="mt-1 block text-2xl" x-text="new Set(rows.map(row => row.id_event)).size"></strong></article><article x-show="tab==='schedules'" class="rounded-xl border border-surface-container-high bg-surface-container-lowest p-4"><p class="text-xs uppercase text-on-surface-variant">Sesi terjadwal</p><strong class="mt-1 block text-2xl" x-text="rows.length"></strong></article></section>
    <div class="flex flex-wrap gap-2"><template x-for="item in [{key:'events',label:'Event'},{key:'speakers',label:'Pembicara'},{key:'schedules',label:'Jadwal'}]" :key="item.key"><button @click="tab=item.key; load()" :class="tab===item.key ? 'bg-primary text-white' : 'bg-surface-container'" class="rounded-lg px-4 py-2 text-sm" x-text="item.label"></button></template></div>
    <p x-show="loading" role="status" class="rounded-xl bg-surface-container-low p-4 text-sm">Memuat konten…</p><p x-show="error" x-text="error" role="alert" class="rounded-xl bg-error-container p-4 text-sm text-error"></p><div x-show="!loading && !error && rows.length===0" class="rounded-xl border p-8 text-center text-sm text-on-surface-variant">Belum ada data untuk bagian ini.</div>
    <div x-show="!loading && !error && rows.length" class="overflow-x-auto rounded-xl border border-surface-container-high bg-surface-container-lowest shadow-sm"><table class="w-full text-left text-sm"><thead><tr class="border-b border-surface-container-high bg-surface-container-low text-xs uppercase"><th class="p-3">Judul</th><th class="p-3">Fakta tersimpan</th><th class="p-3">Aksi</th></tr></thead><tbody><template x-for="row in rows" :key="tab==='events' ? row.id_event : (tab==='speakers' ? row.id_speaker : row.id_schedule)"><tr class="border-b border-surface-container-highest"><td class="p-3 font-semibold" x-text="tab==='events' ? row.nama_event : (tab==='speakers' ? row.nama_speaker : row.nama_kegiatan)"></td><td class="p-3 text-xs text-on-surface-variant" x-text="tab==='events' ? [row.tema, row.deskripsi, row.tanggal_mulai + ' – ' + row.tanggal_selesai, row.lokasi, row.mode_kegiatan, row.status_event].filter(Boolean).join(' · ') : (tab==='speakers' ? [row.institusi, row.negara, row.deskripsi].filter(Boolean).join(' · ') : [row.tanggal, row.waktu_mulai + '–' + row.waktu_selesai, row.lokasi, row.deskripsi].filter(Boolean).join(' · '))"></td><td class="space-x-3 p-3"><button @click="edit(row)" class="text-primary underline">Ubah</button><button @click="remove(row)" class="text-error underline">Hapus</button></td></tr></template></tbody></table></div>
    <div x-show="modal" x-cloak class="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4" @click.self="modal=false"><section class="max-h-[90vh] w-full max-w-xl space-y-4 overflow-y-auto rounded-2xl bg-white p-6"><h2 class="text-lg font-bold" x-text="editing ? 'Ubah konten' : 'Tambah konten'"></h2><p x-show="formError" x-text="formError" role="alert" class="text-sm text-error"></p><form @submit.prevent="save()" class="space-y-3">
        <template x-if="tab==='events'"><div class="space-y-3"><label class="block space-y-1 text-sm">Nama event<input required maxlength="150" x-model="eventForm.nama_event" class="w-full rounded-lg border-surface-container-highest"></label><label class="block space-y-1 text-sm">Tema<input x-model="eventForm.tema" class="w-full rounded-lg border-surface-container-highest"></label><label class="block space-y-1 text-sm">Deskripsi<textarea x-model="eventForm.deskripsi" class="w-full rounded-lg border-surface-container-highest"></textarea></label><div class="grid grid-cols-2 gap-3"><label class="space-y-1 text-sm">Mulai<input required type="date" x-model="eventForm.tanggal_mulai" class="w-full rounded-lg border-surface-container-highest"></label><label class="space-y-1 text-sm">Selesai<input required type="date" x-model="eventForm.tanggal_selesai" class="w-full rounded-lg border-surface-container-highest"></label></div><label class="block space-y-1 text-sm">Lokasi<input x-model="eventForm.lokasi" class="w-full rounded-lg border-surface-container-highest"></label><div class="grid grid-cols-2 gap-3"><label class="space-y-1 text-sm">Mode<select x-model="eventForm.mode_kegiatan" class="w-full rounded-lg border-surface-container-highest"><option>Hybrid</option><option>Daring</option><option>Luring</option></select></label><label class="space-y-1 text-sm">Status<select x-model="eventForm.status_event" class="w-full rounded-lg border-surface-container-highest"><option>Draft</option><option>Aktif</option><option>Selesai</option><option>Arsip</option></select></label></div></div></template>
        <template x-if="tab==='speakers'"><div class="space-y-3"><label class="block space-y-1 text-sm">Event<select required x-model="speakerForm.id_event" class="w-full rounded-lg border-surface-container-highest"><template x-for="event in events" :key="event.id_event"><option :value="event.id_event" x-text="event.nama_event"></option></template></select></label><label class="block space-y-1 text-sm">Nama pembicara<input required x-model="speakerForm.nama_speaker" class="w-full rounded-lg border-surface-container-highest"></label><label class="block space-y-1 text-sm">Institusi<input x-model="speakerForm.institusi" class="w-full rounded-lg border-surface-container-highest"></label><label class="block space-y-1 text-sm">Negara<input x-model="speakerForm.negara" class="w-full rounded-lg border-surface-container-highest"></label><label class="block space-y-1 text-sm">Deskripsi<textarea x-model="speakerForm.deskripsi" class="w-full rounded-lg border-surface-container-highest"></textarea></label></div></template>
        <template x-if="tab==='schedules'"><div class="space-y-3"><label class="block space-y-1 text-sm">Event<select required x-model="scheduleForm.id_event" class="w-full rounded-lg border-surface-container-highest"><template x-for="event in events" :key="event.id_event"><option :value="event.id_event" x-text="event.nama_event"></option></template></select></label><label class="block space-y-1 text-sm">Nama kegiatan<input required x-model="scheduleForm.nama_kegiatan" class="w-full rounded-lg border-surface-container-highest"></label><div class="grid grid-cols-3 gap-3"><label class="space-y-1 text-sm">Tanggal<input required type="date" x-model="scheduleForm.tanggal" class="w-full rounded-lg border-surface-container-highest"></label><label class="space-y-1 text-sm">Mulai<input required type="time" x-model="scheduleForm.waktu_mulai" class="w-full rounded-lg border-surface-container-highest"></label><label class="space-y-1 text-sm">Selesai<input type="time" x-model="scheduleForm.waktu_selesai" class="w-full rounded-lg border-surface-container-highest"></label></div><label class="block space-y-1 text-sm">Lokasi<input x-model="scheduleForm.lokasi" class="w-full rounded-lg border-surface-container-highest"></label><label class="block space-y-1 text-sm">Deskripsi<textarea x-model="scheduleForm.deskripsi" class="w-full rounded-lg border-surface-container-highest"></textarea></label></div></template>
        <div class="flex justify-end gap-2"><button type="button" @click="modal=false" class="rounded-lg border px-4 py-2 text-sm">Batal</button><button :disabled="saving" class="rounded-lg bg-primary px-4 py-2 text-sm font-semibold text-white" x-text="saving ? 'Menyimpan…' : 'Simpan'"></button></div>
    </form></section></div>
</main>
@endsection
